export type CustomerWorkflowTranslationKey = (typeof customerWorkflowTemplateRows)[number][0];

const customerWorkflowTemplates = Object.fromEntries(
  customerWorkflowTemplateRows.map((row) => [
    row[0],
    Object.fromEntries(["en","nl","de","fr","it","ru","es","tr","pt","zh","pl","sq"].map((locale, localeIndex) => [locale, row[localeIndex + 1]])),
  ])
) as Record<CustomerWorkflowTranslationKey, Record<LocaleCode, string>>;

export function customerWorkflowT(
  locale: LocaleCode,
  key: CustomerWorkflowTranslationKey,
  values: Record<string, string | number> = {}
) {
  const template = customerWorkflowTemplates[key][locale] ?? customerWorkflowTemplates[key].en;
  return template.replace(/\{([a-zA-Z][a-zA-Z0-9]*)\}/g, (match, name: string) =>
    Object.prototype.hasOwnProperty.call(values, name) ? String(values[name]) : match
  );
}

export function customerWorkflowExactT(locale: LocaleCode, source: string) {
  if (locale === "en") return source;
  const localeIndex = customerWorkflowLocaleOrder.indexOf(locale as Exclude<LocaleCode, "en">);
  if (localeIndex < 0) return source;
  return customerWorkflowExactTranslations[source]?.[localeIndex] ?? source;
}

export type CustomerNotificationI18nInput = {
  type: "admin_message" | "order_status" | "file_ready" | "additional_upload_enabled" | "system";
  title: string;
  body: string | null;
  status?: string | null;
};

const notificationTypeKeys = {
  admin_message: "notificationTypeAdminMessage",
  order_status: "notificationTypeOrderStatus",
  file_ready: "notificationTypeFileReady",
  additional_upload_enabled: "notificationTypeAdditionalUpload",
  system: "notificationTypeSystem",
} as const satisfies Record<CustomerNotificationI18nInput["type"], CustomerWorkflowTranslationKey>;

const notificationStatusBodyKeys = {
  "New status: New Request": "statusNewRequest",
  "New status: File Check": "statusFileCheck",
  "New status: Customer Info Needed": "statusCustomerInfoNeeded",
  "New status: In Progress": "statusInProgress",
  "New status: Completed": "statusCompleted",
  "New status: Revision": "statusRevision",
  "New status: Cancelled": "statusCancelled",
  "New status: Canceled": "statusCancelled",
} as const satisfies Record<string, CustomerWorkflowTranslationKey>;

const notificationStatusMetadataKeys = {
  new_request: "statusNewRequest",
  file_check: "statusFileCheck",
  customer_info_needed: "statusCustomerInfoNeeded",
  in_progress: "statusInProgress",
  completed: "statusCompleted",
  revision: "statusRevision",
  cancelled: "statusCancelled",
  canceled: "statusCancelled",
} as const satisfies Record<string, CustomerWorkflowTranslationKey>;

export function localizeCustomerNotification(
  locale: LocaleCode,
  item: CustomerNotificationI18nInput,
) {
  const typeLabel = customerWorkflowT(locale, notificationTypeKeys[item.type]);
  if (item.type === "admin_message") {
    return {
      title: customerWorkflowT(locale, "notificationNewMessageTitle"),
      body: item.body,
      typeLabel,
      rawTitle: false,
      rawBody: true,
    };
  }
  if (item.type === "file_ready") {
    return {
      title: customerWorkflowT(locale, "notificationFileReadyTitle"),
      body: customerWorkflowT(locale, "notificationFileReadyBody"),
      typeLabel,
      rawTitle: false,
      rawBody: false,
    };
  }
  if (item.type === "additional_upload_enabled") {
    return {
      title: customerWorkflowT(locale, "notificationAdditionalUploadTitle"),
      body: customerWorkflowT(locale, "notificationAdditionalUploadBody"),
      typeLabel,
      rawTitle: false,
      rawBody: false,
    };
  }
  if (item.type === "order_status") {
    const projectedStatus = typeof item.status === "string"
      ? item.status.trim().toLowerCase().replace(/[\s-]+/g, "_")
      : "";
    const statusKey = projectedStatus
      ? (notificationStatusMetadataKeys as Record<
          string,
          CustomerWorkflowTranslationKey | undefined
        >)[projectedStatus]
      : item.body
      ? (notificationStatusBodyKeys as Record<
          string,
          CustomerWorkflowTranslationKey | undefined
        >)[item.body]
      : undefined;
    if (statusKey) {
      return {
        title: customerWorkflowT(locale, "notificationOrderStatusTitle"),
        body: customerWorkflowT(locale, "notificationNewStatus", {
          status: customerWorkflowT(locale, statusKey),
        }),
        typeLabel,
        rawTitle: false,
        rawBody: false,
      };
    }
  }
  return {
    title: item.title,
    body: item.body,
    typeLabel,
    rawTitle: true,
    rawBody: true,
  };
}

export function customerPasswordErrorT(locale: LocaleCode, source: string) {
  const minimum = source.match(/^Use at least (\d+) characters\.$/);
  if (minimum) return customerWorkflowT(locale, "passwordMinimum", { count: minimum[1] });
  const maximum = source.match(/^Use no more than (\d+) characters\.$/);
  if (maximum) return customerWorkflowT(locale, "passwordMaximum", { count: maximum[1] });
  const keyBySource = {
    "Do not use spaces.": "passwordNoSpaces",
    "Add a lowercase letter.": "passwordLowercase",
    "Add an uppercase letter.": "passwordUppercase",
    "Add a number.": "passwordNumber",
    "Add a symbol.": "passwordSymbol",
    "Choose a less predictable password.": "passwordPredictable",
  } as const satisfies Record<string, CustomerWorkflowTranslationKey>;
  const key = keyBySource[source as keyof typeof keyBySource];
  return key ? customerWorkflowT(locale, key) : customerWorkflowExactT(locale, source);
}
